\begin{figure}[!htbp]
\centering
\newdimen\MainW
\MainW=.90\linewidth

\begin{tikzpicture}[
  node distance=7mm,
  scale=0.96,
  every node/.style={transform shape}
]

\tikzset{
  box/.style={
    rounded corners,
    draw,
    align=left,
    inner sep=5pt,
    text width=\MainW,
    minimum height=8mm
  }
}

\node[box] (step1) {
\textbf{Step 1. Resolution of the Arinkin sheaf}
(Proposition~\ref{prop:resol}).

For a rank-one torsion-free sheaf
\(E\in \Coh^{\heartsuit}(\cC_b)\), construct a left resolution on \(\cH_b\):
\[
    \cdots
    \longrightarrow \mathcal{V}_E^{\oplus k_1}
    \longrightarrow \mathcal{V}_E^{\oplus k_0}
    \longrightarrow \cP_E
    \longrightarrow 0,
\]
where \(\mathcal{V}_E\) is an explicitly constructed vector bundle.
};

\node[box, below=of step1] (step2) {
\textbf{Step 2. Weight estimates}
(Proposition~\ref{prop:VE} and Corollary~\ref{cor:PE}).

Compute the \(\mathbb{G}_m\)-weights of \(\mathcal{V}_E\) for maps
\(\nu\colon \bgm\to \cH\). Combining the estimate with the resolution from
Step~1 gives
\[
    \cP_E \in \widetilde{\LL}(\cH)_{w'}.
\]
};

\node[box, below=of step2] (step3) {
\textbf{Step 3. Globalization}
(Theorem~\ref{thm:PhiO}).

Approximate \(\cH(w)^{\mathrm{ss}}\) by schemes proper over \(\cB\).
Globalizing the pointwise estimate from Step~2 yields
\[
    \Phi(\cO_{\cH(w)^{\mathrm{ss}}})
    \in
    j_{!}\LL(\cH(\chi_0)^{\mathrm{ss}})_{w'}.
\]
};

\node[box, below=of step3] (step4) {
\textbf{Step 4. Whittaker normalization}
(Theorem~\ref{thm:Whit:intro}).

It remains to prove, after restriction to the semistable locus, that
\[
    \Phi(\cO_{\cH(w)^{\mathrm{ss}}})|_{\cH(\chi_0)^{\mathrm{ss}}}
    \cong
    s_{!}\cO_{\cB}|_{\cH(\chi_0)^{\mathrm{ss}}}.
\]
This is shown by reducing to schemes and applying the derived equivalence of
compactified Jacobians from~\cite{MRVF2}.
};

\draw[->] (step1) -- (step2);
\draw[->] (step2) -- (step3);
\draw[->] (step3) -- (step4);

\end{tikzpicture}

\caption{Flowchart of the proof of Theorem~\ref{thm:Whit:intro}.}
\label{fig:flow}
\end{figure}
